import{_ as o,o as r,c as a,a6 as t}from"./chunks/framework.QBF2cGGQ.js";const m=JSON.parse('{"title":"07 · 评测 Evals","description":"","frontmatter":{},"headers":[],"relativePath":"guide/07-evals.md","filePath":"guide/07-evals.md","lastUpdated":1793329740000}'),n={name:"guide/07-evals.md"};function i(p,s,l,g,e,u){return r(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="_07-·-评测-evals" tabindex="-1">07 · 评测 Evals <a class="header-anchor" href="#_07-·-评测-evals" aria-label="Permalink to &quot;07 · 评测 Evals&quot;">​</a></h1><blockquote><p><strong>投入权重：12%</strong> · 这是&quot;demo&quot;和&quot;产品&quot;的唯一分界线，也是绝大多数转岗者跳过的一层。 跳过它，你永远不知道自己是在变好还是变坏。</p></blockquote><h2 id="为什么它是分水岭" tabindex="-1">为什么它是分水岭 <a class="header-anchor" href="#为什么它是分水岭" aria-label="Permalink to &quot;为什么它是分水岭&quot;">​</a></h2><p>传统开发里，你改一行代码，跑测试就知道有没有坏。AI 应用里，你改一个词，输出可能全变，而且&quot;变好还是变坏&quot;没法靠眼看。</p><p>没有评测系统的团队，工作方式是这样的：改 prompt → 试几个例子 → 感觉好像好点了 → 上线 → 用户投诉 → 再改 → 不知道上次改的对不对。这是一个闭环失败的循环，做三个月也不会有积累。</p><p>有评测系统的团队：改 prompt → 跑 200 条评测集 → 看指标差异 → 决定采纳或回滚。<strong>区别不在于聪明程度，在于有没有反馈信号。</strong></p><h2 id="体系" tabindex="-1">体系 <a class="header-anchor" href="#体系" aria-label="Permalink to &quot;体系&quot;">​</a></h2><ul><li><strong>为什么评测是分水岭</strong> <span class="prio prio-must">必须</span> — 没有评测，所有优化都是玄学；有评测，才能做 A/B、才能回滚、才能向老板证明价值。</li><li><strong>三个层次</strong> <span class="prio prio-must">必须</span> — 组件级（检索/生成分开测）、端到端（整体任务）、线上（真实用户指标）。</li><li><strong>评测驱动开发循环</strong> <span class="prio prio-must">必须</span> — 先写评测集 → 再改 prompt/架构 → 跑分 → 决定是否采纳。反过来做就是瞎调。</li><li><strong>评测集的维护</strong> <span class="prio prio-must">必须</span> — 线上 badcase 持续回流进评测集，让它随业务演进。</li><li><strong>评测的成本意识</strong> <span class="prio prio-imp">重要</span> — 每次跑全量评测都花钱。要能按需跑子集，全量只在发版前跑。</li></ul><h2 id="数据集" tabindex="-1">数据集 <a class="header-anchor" href="#数据集" aria-label="Permalink to &quot;数据集&quot;">​</a></h2><ul><li><strong>黄金测试集构建</strong> <span class="prio prio-must">必须</span> — 50~200 条覆盖核心场景的真实问题，人工标注标准答案。起步不要贪多。</li><li><strong>边界与对抗样本</strong> <span class="prio prio-must">必须</span> — 空输入、超长输入、多语言混写、恶意注入、歧义问题。</li><li><strong>难度分层</strong> <span class="prio prio-imp">重要</span> — 简单/中等/困难各占一定比例，否则指标被简单题稀释。</li><li><strong>样本代表性</strong> <span class="prio prio-must">必须</span> — 从真实日志采样，不要自己编题。自编题会系统性偏简单。</li><li><strong>标准答案的形态</strong> <span class="prio prio-imp">重要</span> — 有些任务没有唯一答案（写作），这时标&quot;必须包含的要点&quot;和&quot;必须避免的错误&quot;。</li><li><strong>数据集版本管理</strong> <span class="prio prio-imp">重要</span> — 改了评测集就不能和历史分数直接比。要记录版本。</li></ul><h2 id="llm-as-a-judge" tabindex="-1">LLM-as-a-Judge <a class="header-anchor" href="#llm-as-a-judge" aria-label="Permalink to &quot;LLM-as-a-Judge&quot;">​</a></h2><ul><li><strong>原理</strong> <span class="prio prio-must">必须</span> — 用强模型给输出打分。规模化评测的唯一现实手段。</li><li><strong>位置偏差</strong> <span class="prio prio-must">必须</span> — 倾向选第一个。解法：交换顺序各跑一次取平均。</li><li><strong>长度偏差</strong> <span class="prio prio-must">必须</span> — 倾向给长答案高分。解法：评分标准里显式要求&quot;简洁不扣分&quot;。</li><li><strong>自我偏好</strong> <span class="prio prio-must">必须</span> — 同一家模型评自己会偏高。解法：用不同厂模型做 judge。</li><li><strong>评分标准要可执行</strong> <span class="prio prio-must">必须</span> — &quot;回答质量 1-5 分&quot;是废的，&quot;是否引用了给定材料、是否有编造、是否回答了问题&quot;才可用。</li><li><strong>与人工对齐</strong> <span class="prio prio-must">必须</span> — judge 上线前要用 50 条人工标注校准，看一致率。<strong>低于 80% 不可信</strong>（这是经验阈值，具体看任务容忍度）。</li><li><strong>Pairwise vs Pointwise</strong> <span class="prio prio-imp">重要</span> — 两两比较更稳（人也是这样判断的），绝对打分更省。</li><li><strong>Judge 的 prompt 也是 prompt</strong> <span class="prio prio-imp">重要</span> — 它同样需要版本管理和评测。别用一个没验证过的 judge 去评生产系统。</li></ul><h2 id="人工评估" tabindex="-1">人工评估 <a class="header-anchor" href="#人工评估" aria-label="Permalink to &quot;人工评估&quot;">​</a></h2><ul><li><strong>标注流程设计</strong> <span class="prio prio-must">必须</span> — 明确任务定义、评分维度、边界案例，先试标 20 条再全量。</li><li><strong>标注一致性</strong> <span class="prio prio-imp">重要</span> — Cohen kappa 等指标衡量。一致性低说明标准不清，先改标准。</li><li><strong>成本控制</strong> <span class="prio prio-imp">重要</span> — 人工评估贵，只用于校准 judge 和关键决策点。</li></ul><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><ul><li><strong>promptfoo</strong> <span class="prio prio-must">必须</span> — 配置化跑 prompt 回归测试，CI 友好，上手最快。</li><li><strong>DeepEval</strong> <span class="prio prio-must">必须</span> — Python 单测风格，指标齐全。</li><li><strong>RAGAS</strong> <span class="prio prio-must">必须</span> — RAG 专用指标体系，直接可用。</li><li><strong>LangSmith Evals</strong> <span class="prio prio-imp">重要</span> — 与 LangChain 生态集成好。</li><li><strong>Braintrust / Arize Phoenix</strong> <span class="prio prio-imp">重要</span> — 商业与开源的可观测+评测一体方案。</li><li><strong>传统指标为什么失效</strong> <span class="prio prio-must">必须</span> — BLEU / ROUGE 只看词重叠，语义正确但换个说法就判错。别用。</li></ul><h2 id="线上指标" tabindex="-1">线上指标 <a class="header-anchor" href="#线上指标" aria-label="Permalink to &quot;线上指标&quot;">​</a></h2><ul><li><strong>采纳率</strong> <span class="prio prio-must">必须</span> — 生成的代码/文案被直接采用的比例。最硬的产品指标。</li><li><strong>任务完成率</strong> <span class="prio prio-must">必须</span> — 用户是否真的完成了目标，而不只是&quot;聊了几句&quot;。</li><li><strong>人工介入率</strong> <span class="prio prio-must">必须</span> — 需要人工纠正的比例。Agent 场景核心指标。</li><li><strong>重试率与放弃率</strong> <span class="prio prio-imp">重要</span> — 反复重新生成说明效果差。</li><li><strong>成本/请求</strong> <span class="prio prio-must">必须</span> — 单位经济模型的基础。</li><li><strong>延迟分位 P50/P95/P99</strong> <span class="prio prio-must">必须</span> — 平均值会骗人，必须看分位。</li><li><strong>A/B 实验设计</strong> <span class="prio prio-imp">重要</span> — 分流、样本量、显著性。别用&quot;我感觉&quot;代替实验。</li><li><strong>北极星指标的陷阱</strong> <span class="prio prio-imp">重要</span> — 只优化采纳率会导致输出变短变保守。要配一组制衡指标。</li></ul><h2 id="tool-calling-评测" tabindex="-1">Tool Calling 评测 <a class="header-anchor" href="#tool-calling-评测" aria-label="Permalink to &quot;Tool Calling 评测&quot;">​</a></h2><p>工具调用是 Agent 的地基。<strong>地基歪了，上面评测什么都是假的。</strong> 这一层可以拆成五个可量化指标，每个都能单独跑。</p><ul><li><strong>Tool Selection Accuracy（工具选择准确率）</strong> <span class="prio prio-must">必须</span> — 给定问题，模型选对工具的比例。<strong>这是最基础也最容易被忽略的指标</strong>，工具一多就掉。</li><li><strong>参数正确率</strong> <span class="prio prio-must">必须</span> — 选对工具但参数填错等于失败。要逐字段比对：必填项缺失率、类型错误率、枚举越界率、日期格式错误率。</li><li><strong>错误恢复率</strong> <span class="prio prio-must">必须</span> — 工具返回错误后，模型能否根据错误信息修正参数重试。<strong>这是区分&quot;能跑&quot;和&quot;能上生产&quot;的关键指标</strong>，很多 demo 在这一项上是 0。</li><li><strong>无效调用率</strong> <span class="prio prio-must">必须</span> — 调用了不存在或不适用的工具。说明工具描述写得不清楚，或者工具太多。</li><li><strong>重复调用率</strong> <span class="prio prio-imp">重要</span> — 相同参数重复调用同一工具。浪费钱，说明模型没读到上一步结果。</li><li><strong>不必要调用率</strong> <span class="prio prio-imp">重要</span> — 明明可以直接回答却去调工具。反映 system prompt 里&quot;什么时候该用工具&quot;没说清。</li><li><strong>权限违规测试</strong> <span class="prio prio-must">必须</span> — 构造诱导性输入，看模型会不会调它没权限的工具。<strong>这是安全评测，不是效果评测</strong>，必须单列。</li><li><strong>并行调用的正确性</strong> <span class="prio prio-imp">重要</span> — 有依赖关系的调用被并行发出去了吗？会导致参数互相缺失。</li><li><strong>怎么测</strong> <span class="prio prio-must">必须</span> — 构造 <code>(问题, 期望工具, 期望参数)</code> 三元组，跑批比对。<strong>不需要真实执行工具</strong>，mock 掉就能测选择层。</li></ul><h2 id="agent-评测" tabindex="-1">Agent 评测 <a class="header-anchor" href="#agent-评测" aria-label="Permalink to &quot;Agent 评测&quot;">​</a></h2><p>Agent 的路径不唯一，所以不能只比最终答案。要同时测&quot;结果&quot;和&quot;过程&quot;。</p><ul><li><strong>Step Success Rate（单步成功率）</strong> <span class="prio prio-must">必须</span> — 每一步做对的比例。<strong>这个数字直接决定十步任务的成败</strong>（0.95^10 ≈ 0.6）。</li><li><strong>Completion Rate（任务完成率）</strong> <span class="prio prio-must">必须</span> — 端到端达成目标的比例。最硬的结果指标。</li><li><strong>Loop Detection（循环检测）</strong> <span class="prio prio-must">必须</span> — 有没有反复做同一件事。指标：平均步数、重复动作占比、触达最大步数上限的比例。</li><li><strong>Tool Efficiency（工具效率）</strong> <span class="prio prio-imp">重要</span> — 完成同一任务用的工具调用次数。<strong>和&quot;人工最少需要几步&quot;对比</strong>，多出来的就是浪费。</li><li><strong>人工接管率</strong> <span class="prio prio-must">必须</span> — 需要人介入才能继续的比例。Agent 场景的核心产品指标。</li><li><strong>中断恢复成功率</strong> <span class="prio prio-imp">重要</span> — 从 checkpoint 恢复后能否正确继续。<strong>必须专门造一个&quot;跑到一半杀掉进程&quot;的测试</strong>，否则上线才发现恢复是坏的。</li><li><strong>成本-成功率关系</strong> <span class="prio prio-must">必须</span> — 只报成功率是耍流氓。要报&quot;成功率 / 单任务成本&quot;，并画出曲线：加钱能不能换到准确率？换不到就说明瓶颈不在模型。</li><li><strong>过程合理性</strong> <span class="prio prio-imp">重要</span> — 结果对了但路径荒谬（比如删库重建），也是失败。用 LLM-judge 评轨迹，或用规则检查&quot;是否调用了禁止工具&quot;。</li><li><strong>轨迹回放</strong> <span class="prio prio-must">必须</span> — 每次评测要能回放完整轨迹（每步的输入输出）。<strong>不能回放的评测系统没有排障价值</strong>。</li><li><strong>评测环境的确定性</strong> <span class="prio prio-must">必须</span> — 工具要 mock 或指向测试环境，数据要可重置。<strong>否则同一个用例跑两次结果不同，评测就没意义</strong>。</li></ul><h2 id="本章对应的面试题" tabindex="-1">本章对应的面试题 <a class="header-anchor" href="#本章对应的面试题" aria-label="Permalink to &quot;本章对应的面试题&quot;">​</a></h2><p>共 20 题，见 <a href="/ai-eng-roadmap/guide/15-interview#f-评测-20-题-第二重灾区">15 · 面试题库 · F 组</a>。</p><p>这一章是&quot;做过&quot;和&quot;做好过&quot;的分界。如果面试只能准备一个知识点，就准备这里——因为它决定了你所有其他回答的可信度。</p><p>三个必答题：<strong>F1 怎么评测没有标准答案的任务</strong>、<strong>F2 LLM-judge 的偏差怎么处理</strong>、<strong>F3 评测集多少条、怎么来的</strong>。</p><p><strong>加分回答</strong>：主动提&quot;我们除了最终答案，还测了工具选择准确率和错误恢复率，因为十步任务里单步 95% 只剩六成&quot;。这句话能直接把话题引到你最熟的地方。</p>',29)])])}const q=o(n,[["render",i]]);export{m as __pageData,q as default};
